// TestActionNames asserts every announced service action name is a registered constant.
func TestActionNames(t *testing.T) {

	names := []op.ActionName{
		provider.Disable,
		provider.Enable,
		provider.Enabled,
		provider.Exists,
		provider.Restart,
		provider.Running,
		provider.Start,
		provider.Stop,
	}
	for _, name := range names {
		a := getAction(t, name)
		if got := a.Name(); got != name {
			t.Errorf("Name() = %q, want %q", got, name)
		}
	}
}

